results.command:
Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=True' | ForEach-Object {
    $adapter = $_
    $r = Invoke-CimMethod -InputObject $adapter -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = 2 }
    switch ($r.ReturnValue) {
        0 { "$($adapter.Description): NetBIOS disabled" }
        1 { Write-Warning "$($adapter.Description): disabled, REBOOT REQUIRED" }
        default { Write-Warning "$($adapter.Description): failed, ReturnValue=$($r.ReturnValue)" }
    }
}
